using PrimaryKey = T;

struct Product {
  PrimaryKey<int> product_id;
  std::string name;
  float price;
  std::string category;
  int stock;
};

/**
 * Function: Perform efficient batch insertion of product data using a transaction.
 * 
 * @param products List of products to insert
 * @return true if all inserts succeed, false otherwise
 */
bool batch_insert_products(const std::vector<Product>& products) {
  // We use monadic operations (.and_then) to chain the database operations.
  // If any step fails, the chain short-circuits and the error is propagated.
  // std::cref is used to pass the products vector by reference to avoid unnecessary copying.
  auto result = sqlgen::sqlite::connect("test_db.sqlite")
                    .and_then(sqlgen::drop<Product> | sqlgen::if_exists)
                    .and_then(sqlgen::create_table<Product>)
                    .and_then(sqlgen::begin_transaction)
                    .and_then(sqlgen::write(std::cref(products)))
                    .and_then(sqlgen::commit);

  // Return true if the entire chain of operations succeeded
  return result.has_value();
}

}  // namespace batch_insert_products
