    SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType, Args...>,
    false> {
  using TableTupleType = table_tuple_t<TableOrQueryType, AliasType, JoinsType>;
  using Type = fields_to_named_tuple_t<TableTupleType, FieldsType>;
};

