// Assuming PrimaryKey and Timestamp are provided by the environment (e.g., rfl)
template <class T>
using PrimaryKey = T;

template <rfl::internal::StringLiteral _fmt>
using Timestamp = std::string;

struct PageVisit {
  PrimaryKey<int> visit_id;
  std::string url;
  Timestamp<"%Y-%m-%d %H:%M:%S"> visit_time;
};

struct DailyTraffic {
  std::string visit_date;
  int total_visits;
  int unique_pages;
};

struct DailyTrafficView {
  static constexpr const char* tablename = "DailyTrafficView";
  static constexpr bool is_view = true;
  std::string visit_date;
  int total_visits;
  int unique_pages;
};

/**
 * Function: Calculate daily traffic metrics from a log table.
 * 
 * @return List of daily traffic metrics
 */
std::vector<DailyTraffic> query_daily_traffic_metrics() {
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Build the query
  auto query = sqlgen::select_from<PageVisit>(
                   "strftime('%Y-%m-%d', visit_time)"_c | sqlgen::as<"visit_date">,
                   sqlgen::count() | sqlgen::as<"total_visits">,
                   sqlgen::count_distinct("url"_c) | sqlgen::as<"unique_pages">) |
               sqlgen::group_by("visit_date"_c) |
