namespace query_product_sales_report {

// Assuming PrimaryKey is available in sqlgen namespace
using sqlgen::PrimaryKey;

struct Product {
  PrimaryKey<int> product_id;
  std::string category;
};

struct Sale {
  PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct CategoryReport {
  std::string category;
  int total_qty;
  double total_amt;
};

struct ProductSalesReport {
  static constexpr const char* tablename = "ProductSalesReport";
  static constexpr bool is_view = true;
  std::string category;
  int total_qty;
  double total_amt;
};

std::vector<CategoryReport> query_product_sales_report() {
    using namespace sqlgen;

    // Connect to the SQLite database
    auto conn = sqlite::connect("test_db.sqlite");

    // Define columns with aliases for clarity
    auto p_cat = col<"category", "p">;
    auto p_pid = col<"product_id", "p">;
    auto s_pid = col<"product_id", "s">;
    auto s_qty = col<"quantity", "s">;
    auto s_amt = col<"amount", "s">;

    // Construct the inner query:
    // 1. Select category, sum(quantity), sum(amount)
    // 2. Join Product and Sale tables on product_id
    // 3. Group by category
    auto inner_query = select_from<Product, "p">(
                           p_cat,
                           sum(s_qty).as<"total_qty">(),
                           sum(s_amt).as<"total_amt">())
                           .inner_join<Sale, "s">(p_pid == s_pid)
                           .group_by(p_cat);

    // Construct the outer query to filter results (simulating HAVING clause):
    // 1. Select from the inner query (aliased as "sub")
    // 2. Filter where total_amt > 5000
    // 3. Map result to CategoryReport vector
    auto query = select_from<"sub">(inner_query,
                                    col<"category">,
                                    col<"total_qty">,
                                    col<"total_amt">)
                     .where(col<"total_amt"> > 5000.0)
                     | to<std::vector<CategoryReport>>;

    // Execute the query and return the result, or an empty vector on failure
    return query(conn).value_or(std::vector<CategoryReport>{});
}

}  // namespace query_product_sales_report
