#include "sqlgen/literals.hpp"
#include "sqlgen/sqlite/connect.hpp"

namespace schema_manage_indexes {

  // Assuming PrimaryKey is provided by the sqlgen library
  using sqlgen::PrimaryKey;

  struct Product {
    PrimaryKey<int> product_id;
    std::string sku;
    std::string name;
    std::string category;
    double price;
  };

  bool manage_indexes() {
    using namespace sqlgen::literals;

    // Connect to the SQLite database "test_db.sqlite"
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // 1. Create Product Table
    // Use the pipe operator to apply "IF NOT EXISTS" logic
    auto res = (sqlgen::create_table<Product> | sqlgen::if_not_exists)(conn);

    // 2. Create standard index on 'category'
    // SQL: CREATE INDEX IF NOT EXISTS idx_product_category ON Product(category);
    res = (sqlgen::create_index<"idx_product_category", Product>("category"_c) 
           | sqlgen::if_not_exists)(res);

    // 3. Create unique index on 'sku'
    // SQL: CREATE UNIQUE INDEX IF NOT EXISTS idx_product_sku ON Product(sku);
    res = (sqlgen::create_unique_index<"idx_product_sku", Product>("sku"_c) 
           | sqlgen::if_not_exists)(res);

    // 4. Create composite index on 'name' and 'price'
    // SQL: CREATE INDEX IF NOT EXISTS idx_product_name_price ON Product(name, price);
    res = (sqlgen::create_index<"idx_product_name_price", Product>("name"_c, "price"_c) 
           | sqlgen::if_not_exists)(res);

    // Return true if all operations were successful
    // The Result object is cast to bool to indicate success/failure
    return static_cast<bool>(res);
  }

}  // namespace schema_manage_indexes
