#pragma once

#include <string>
#include <iostream>
#include "sqlgen/sqlite/connect.hpp"

namespace schema_migration_add_column {

// Assuming PrimaryKey and auto_incr are defined in the library's context or other headers.
// We retain the structs as provided in the requirements.

struct User {
  PrimaryKey<int> user_id;
  std::string username;
};

struct UserAfter {
  PrimaryKey<int, auto_incr> user_id;
  std::string username;
  std::string phone_number;
  bool is_active;
};

/**
 * Function: Perform schema migration to add new columns.
 * 
 * @return true if migration succeeds, false otherwise
 */
bool migration_add_column() {
  try {
    // Connect to the SQLite database "test_db.sqlite"
    // sqlgen::sqlite::connect returns a connection object (or a Result containing it)
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // SQL statements to modify the schema
    std::string add_phone_sql = "ALTER TABLE User ADD COLUMN phone_number VARCHAR(20);";
    std::string add_active_sql = "ALTER TABLE User ADD COLUMN is_active INTEGER DEFAULT 1;";

    // Helper lambda to execute SQL and handle "duplicate column" error gracefully.
    // This ensures the migration is idempotent (can be run multiple times).
    auto execute_safely = [&](const std::string& sql) -> bool {
      try {
        // Execute the raw SQL statement.
        // We assume the connection object exposes an execute() method that throws on failure.
        conn.execute(sql);
        return true;
      } catch (const std::exception& e) {
        std::string err_msg = e.what();

        // Check if the error is due to the column already existing.
        // SQLite typically returns "duplicate column name: <column>"
        if (err_msg.find("duplicate column name") != std::string::npos) {
          return true; // Column already exists, treat as success
        }

        // Log unexpected errors
        std::cerr << "Error executing SQL: " << sql << "\nReason: " << err_msg << std::endl;
        return false;
      }
    };

    // 1. Add phone_number column
    if (!execute_safely(add_phone_sql)) {
      return false;
    }

    // 2. Add is_active column
    if (!execute_safely(add_active_sql)) {
      return false;
    }

    return true;

  } catch (const std::exception& e) {
    std::cerr << "Fatal error during migration: " << e.what() << std::endl;
    return false;
  }
}

} // namespace schema_migration_add_column
