namespace transaction_transfer_funds {

struct Account {
  PrimaryKey<int> account_id;
  double balance;
};

bool transfer_funds(int from_account_id, int to_account_id, double amount) {
  using namespace sqlgen::literals;

  // 1. Connect to the SQLite database
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return false;
  }
  auto conn = *conn_res;

  // 2. Start a transaction
  auto trans_res = sqlgen::begin_transaction(conn);
  if (!trans_res) {
    return false;
  }
  auto trans = *trans_res;

  // 3. Update sender: deduct amount if balance is sufficient
  // SQL: UPDATE Account SET balance = balance - amount WHERE account_id = ? AND balance >= ?
  auto update_sender = sqlgen::update<Account>(
      "balance"_c.set("balance"_c - amount)
  ).where(
      "account_id"_c == from_account_id && "balance"_c >= amount
  );

  // Execute update on the transaction's connection
  auto sender_res = update_sender(trans->conn());
  if (!sender_res) {
    sqlgen::rollback(trans);
    return false;
  }

  // Verify sufficient funds: Check if any row was updated.
  // If 0 rows were updated, it means the condition (balance >= amount) failed or account doesn't exist.
  if (trans->conn()->changes() == 0) {
    sqlgen::rollback(trans);
    return false;
  }

  // 4. Update receiver: add amount
  // SQL: UPDATE Account SET balance = balance + amount WHERE account_id = ?
  auto update_receiver = sqlgen::update<Account>(
      "balance"_c.set("balance"_c + amount)
  ).where(
      "account_id"_c == to_account_id
  );

  auto receiver_res = update_receiver(trans->conn());
  if (!receiver_res) {
    sqlgen::rollback(trans);
    return false;
  }

  // Verify receiver exists (check if any row was updated)
  if (trans->conn()->changes() == 0) {
    sqlgen::rollback(trans);
    return false;
  }

  // 5. Commit the transaction
  auto commit_res = sqlgen::commit(trans);
  if (!commit_res) {
    return false;
  }

  return true;
}

}  // namespace transaction_transfer_funds
