  PrimaryKey<int> order_id;
  std::string status;
  DateTime order_date;
  double total_amount;
};

int update_order_status() {
  // Connect to the SQLite database
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res.has_value()) {
    return 0;
  }

  auto conn = conn_res.value();
  int affected_rows = 0;

  // 1. Update the status of all 'pending' orders older than 7 days to 'expired'
  // We execute the raw SQL directly to easily retrieve the number of affected rows,
  // as the query builder's update_impl transforms and hides the affected rows count.
  std::string sql_expired = 
      "UPDATE \"Order\" "
      "SET status = 'expired' "
      "WHERE status = 'pending' AND order_date < DATE('now', '-7 days');";

  auto res_expired = conn->execute(sql_expired);
  if (res_expired.has_value()) {
      affected_rows += res_expired.value();
  }

  // 2. Update the status of 'shipped' orders to 'delivered' (simulated delivery confirmation)
  std::string sql_delivered = 
      "UPDATE \"Order\" "
      "SET status = 'delivered' "
      "WHERE status = 'shipped';";

  auto res_delivered = conn->execute(sql_delivered);
  if (res_delivered.has_value()) {
      affected_rows += res_delivered.value();
  }

  return affected_rows;
}

} // namespace update_order_status
