  static constexpr bool is_view = true;
  std::string product_name;
  int total_quantity;
  double total_revenue;
};

/**
 * Function: Create a view SalesSummary that aggregates sales by product.
 * 
 * @return true if view creation succeeds, false otherwise
 */
bool create_view_sales_summary() {
  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Define columns with explicit table aliases
  // 's' alias for Sale table, 'p' alias for Product table
  auto p_name = Col<"name", "p">{};
  auto s_quantity = Col<"quantity", "s">{};
  auto s_amount = Col<"amount", "s">{};
  auto s_product_id = Col<"product_id", "s">{};
  auto p_product_id = Col<"product_id", "p">{};

  // Construct the SELECT query for the view
  // Corresponds to:
  // SELECT p.name as product_name, SUM(s.quantity) as total_quantity, SUM(s.amount) as total_revenue
  // FROM Sale s
  // JOIN Product p ON s.product_id = p.product_id
  // GROUP BY p.name
  auto query = select_from<Sale, "s">(
                   p_name | as<"product_name">,
                   sum(s_quantity) | as<"total_quantity">,
                   sum(s_amount) | as<"total_revenue">
               )
               | join<Product, "p">(s_product_id == p_product_id)
               | group_by(p_name);

  // Execute the create view command
  // Using create_as with if_not_exists to handle "IF NOT EXISTS" logic for SQLite
  // create_as detects that SalesSummary is a view via `is_view = true`
  auto result = (create_as<SalesSummary>(query) | if_not_exists)(conn);

  return result ? true : false;
}

}  // namespace schema_create_view_sales_summary
