#pragma once

#include <optional>
#include <string>
#include <vector>

#include <sqlgen.hpp>
#include <sqlgen/sqlite/connect.hpp>

namespace right_join_departments_projects {

template <class T>
using PrimaryKey = T;

struct Department {
  PrimaryKey<int> department_id;
  std::string name;
};

struct Project {
  PrimaryKey<int> project_id;
  int department_id;
  std::string name;
};

struct DepProj {
  std::optional<std::string> department_name;
  std::string project_name;
};

/**
 * description: right_join_departments_projects.
 * This function demonstrates how to perform a right join between departments and projects using sqlgen read API.
 * It returns a vector of DepProj structs, where each struct contains the department name (if available) and the project name.
 * Returns: std::vector<DepProj>.
 */
std::vector<DepProj> right_join_departments_projects() {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  using namespace sqlgen::literals;

  // To include all departments via a RIGHT JOIN, Department must be the right table.
  // Project will be the left table and can be null if a department has no projects.
  auto join_cond = sqlgen::col<"department_id", "project"> == sqlgen::col<"department_id", "d">;

  // We use the QueryType overload by passing Department{} to ensure table_or_query is exactly of type Department
  auto right_join_dept = sqlgen::right_join<"d">(Department{}, join_cond);

  // The RowType reflects the left table (Project, which is optional) and the right joined table (Department)
  using RowType = rfl::Tuple<std::optional<Project>, decltype(right_join_dept)>;

  // Execute the read query
  auto rows_res = sqlgen::read<std::vector<RowType>>(conn);

  std::vector<DepProj> result;

  // Process the results if the query was successful
  auto rows = rows_res.value_or(std::vector<RowType>{});
  for (const auto& row : rows) {
    const auto& proj_opt = rfl::get<0>(row);
    const auto& dept_join = rfl::get<1>(row);

    DepProj dp;
    // Department is the preserved table in the RIGHT JOIN, so it's always available
    dp.department_name = dept_join.table_or_query.name;

    // Project might be null if the department has no projects
    if (proj_opt.has_value()) {
      dp.project_name = proj_opt.value().name;
    } else {
      dp.project_name = "";
    }

    result.push_back(dp);
  }

  return result;
}

}  // namespace right_join_departments_projects
