#pragma once

#include <string>
#include <vector>

#include <sqlgen.hpp>
#include <sqlgen/sqlite/connect.hpp>
#include <sqlgen/create_table.hpp>
#include <sqlgen/select_from.hpp>
#include <sqlgen/col.hpp>
#include <sqlgen/joins.hpp>
#include <sqlgen/where.hpp>
#include <sqlgen/group_by.hpp>
#include <sqlgen/to.hpp>
#include <sqlgen/literals.hpp>

namespace analyze_social_network {

template <class T>
struct PrimaryKey {
  T value;
};

template <rfl::internal::StringLiteral _format>
struct Timestamp {
  std::string value;
};

struct User {
  PrimaryKey<int> user_id;
  std::string username;
};

struct Friendship {
  int user1_id;
  int user2_id;
  Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct FriendConnection {
  std::string user1_name;
  std::string user2_name;
};

/**
 * Analyze social network data by creating temporary SQL tables for User and Friendship.
 * Returns: std::vector<FriendConnection>.
 */
std::vector<FriendConnection> analyze_social_network_impl(const std::vector<User>& users, const std::vector<Friendship>& friendships) {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    auto conn_res = sqlite::connect("test_db.sqlite");
    if (!conn_res) {
        return {};
    }
    auto conn = conn_res.value();

    // 1. Create tables
    conn->execute("CREATE TABLE IF NOT EXISTS User ("
                  "user_id INTEGER PRIMARY KEY, "
                  "username VARCHAR(50) NOT NULL UNIQUE, "
                  "email VARCHAR(100), "
                  "join_date DATETIME, "
                  "city VARCHAR(50)"
                  ");");

    conn->execute("CREATE TABLE IF NOT EXISTS Friendship ("
                  "user1_id INTEGER, "
                  "user2_id INTEGER, "
                  "created_at DATETIME, "
                  "PRIMARY KEY (user1_id, user2_id)"
                  ");");

    // Clear existing data for idempotency
    conn->execute("DELETE FROM Friendship;");
    conn->execute("DELETE FROM User;");

    // Insert data
    for (const auto& u : users) {
        auto get_id = [](const auto& id) -> int {
            if constexpr (requires { id.value(); }) return id.value();
            else if constexpr (requires { id.value; }) return id.value;
            else return static_cast<int>(id);
        };
        std::string sql = "INSERT INTO User (user_id, username) VALUES (" + 
                          std::to_string(get_id(u.user_id)) + ", '" + u.username + "');";
        conn->execute(sql);
    }

    for (const auto& f : friendships) {
        std::string sql = "INSERT INTO Friendship (user1_id, user2_id, created_at) VALUES (" + 
                          std::to_string(f.user1_id) + ", " + std::to_string(f.user2_id) + ", '2023-01-01 00:00:00');";
        conn->execute(sql);
    }

    // 1. Mutual friends
    conn->execute("SELECT u1.username, u2.username, COUNT(f1.user2_id) as mutual_friends "
                  "FROM User u1 "
                  "INNER JOIN Friendship f1 ON u1.user_id = f1.user1_id "
                  "INNER JOIN Friendship f2 ON f1.user2_id = f2.user1_id "
                  "INNER JOIN User u2 ON f2.user2_id = u2.user_id "
                  "WHERE u1.user_id < u2.user_id "
                  "  AND EXISTS ( "
                  "    SELECT 1 FROM Friendship f3 "
                  "    WHERE f3.user1_id = u1.user_id AND f3.user2_id = u2.user_id "
                  "  ) "
                  "GROUP BY u1.user_id, u2.user_id "
                  "HAVING COUNT(f1.user2_id) > 0;");

    // 2. Users with more than N friends
    conn->execute("SELECT u.user_id, u.username, COUNT(f.user2_id) as friend_count "
                  "FROM User u "
                  "LEFT JOIN Friendship f ON u.user_id = f.user1_id "
                  "GROUP BY u.user_id, u.username "
                  "HAVING friend_count > ( "
                  "  SELECT AVG(friend_count) "
                  "  FROM (SELECT COUNT(*) as friend_count FROM Friendship GROUP BY user1_id) "
                  ") "
                  "ORDER BY friend_count DESC;");

    // 3. Friend-of-friend relationships
    conn->execute("SELECT u1.username, u2.username "
                  "FROM User u1 "
                  "INNER JOIN Friendship f1 ON u1.user_id = f1.user1_id "
                  "INNER JOIN Friendship f2 ON f1.user2_id = f2.user1_id "
                  "INNER JOIN User u2 ON f2.user2_id = u2.user_id "
                  "WHERE u1.user_id < u2.user_id "
                  "  AND NOT EXISTS ( "
                  "    SELECT 1 FROM Friendship f3 "
                  "    WHERE f3.user1_id = u1.user_id AND f3.user2_id = u2.user_id "
                  "  ) "
                  "GROUP BY u1.user_id, u2.user_id "
                  "HAVING COUNT(f1.user2_id) = 1;");

    // 4. Count friends per user
    conn->execute("SELECT u.username, COUNT(f.user2_id) as count "
                  "FROM User u "
                  "LEFT JOIN Friendship f ON u.user_id = f.user1_id "
                  "GROUP BY u.user_id "
                  "ORDER BY count DESC;");

    // 5. Users in the same city who are not yet friends
    conn->execute("SELECT u1.username, u2.username "
                  "FROM User u1 "
                  "INNER JOIN User u2 ON u1.city = u2.city AND u1.user_id < u2.user_id "
                  "WHERE NOT EXISTS ( "
                  "  SELECT 1 FROM Friendship f "
                  "  WHERE f.user1_id = u1.user_id AND f.user2_id = u2.user_id "
                  ");");

    // Return friend-of-friend relationships using sqlgen query builder
    auto fof_query = select_from<User, "u1">(
            col<"username", "u1">.as<"user1_name">(),
            col<"username", "u2">.as<"user2_name">()
        )
        | inner_join<Friendship, "f1">(col<"user_id", "u1"> == col<"user1_id", "f1">)
        | inner_join<Friendship, "f2">(col<"user2_id", "f1"> == col<"user1_id", "f2">)
        | inner_join<User, "u2">(col<"user2_id", "f2"> == col<"user_id", "u2">)
        | where(col<"user_id", "u1"> < col<"user_id", "u2">)
        | group_by(col<"user_id", "u1">, col<"user_id", "u2">)
        | to<std::vector<FriendConnection>>();

    auto result = fof_query(conn);
    return result.value_or(std::vector<FriendConnection>{});
}

}  // namespace analyze_social_network
