      sqlgen::col<"product_id">,
      sqlgen::col<"name">,
      sqlgen::abs(sqlgen::col<"price">) | sqlgen::as<"abs_price">,
      sqlgen::ceil(sqlgen::col<"price">) | sqlgen::as<"ceil_price">,
      sqlgen::floor(sqlgen::col<"price">) | sqlgen::as<"floor_price">,
