      sqlgen::sin(sqlgen::col<"discount_rate">) | sqlgen::as<"sin_discount">,
      sqlgen::cos(sqlgen::col<"discount_rate">) | sqlgen::as<"cos_discount">,
      sqlgen::tan(sqlgen::col<"discount_rate">) | sqlgen::as<"tan_discount">,
      sqlgen::sqrt(sqlgen::col<"quantity">) | sqlgen::as<"sqrt_quantity">
  ) | sqlgen::to<std::vector<MathAnalysis>>;

  // Execute the query and return the results
  auto res = query(conn);
  if (res.has_value()) {
    return res.value();
  }

  return {};
}

