#pragma once

#include <optional>
#include <vector>
#include <string>
#include <sqlgen.hpp>

namespace calculate_order_metrics {

// Assuming PrimaryKey is provided by the environment (e.g., rfl::PrimaryKey)
template <class T>
using PrimaryKey = rfl::PrimaryKey<T>;

struct OrderItem {
  PrimaryKey<int> item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  std::optional<double> discount_rate;
  std::optional<double> tax_rate;
};

struct OrderMetrics {
  int item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  double discount_rate;
  double tax_rate;
  double gross_total;
  double discounted_total;
  double final_total;
  double unit_cost;
  int quantity_group;
  double estimated_profit;
};

// Helper to safely extract the underlying ID value regardless of the PrimaryKey implementation
template <typename T>
auto extract_id(const T& id_obj) {
    if constexpr (requires { id_obj.value; }) {
        return id_obj.value;
    } else if constexpr (requires { id_obj.id; }) {
        return id_obj.id;
    } else if constexpr (requires { id_obj.value(); }) {
        return id_obj.value();
    } else {
        return id_obj;
    }
}

/**
 * Calculate per-item order metrics by loading the provided items into a temporary SQLite table
 * and evaluating SQL expressions for totals, discounts, taxes, cost, grouping, and estimated profit.
 * @param items Vector of OrderItem records to analyze.
 * @return std::vector<OrderMetrics> Analysis results for each order item.
 */
std::vector<OrderMetrics> calculate_order_metrics_impl(const std::vector<OrderItem>& items) {
  // Connect to the SQLite database
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res.has_value()) {
    return {};
  }
  auto conn = conn_res.value();

  // Create the temporary table
  conn->execute("CREATE TABLE IF NOT EXISTS OrderItem ("
                "item_id INTEGER PRIMARY KEY, "
                "order_id INTEGER NOT NULL, "
                "product_id INTEGER NOT NULL, "
                "unit_price REAL NOT NULL, "
                "quantity INTEGER NOT NULL, "
                "discount_rate REAL, "
                "tax_rate REAL)");

  // Clear any existing data
  conn->execute("DELETE FROM OrderItem");

  // Insert items into the table
  // We substitute missing optional values with 0.0 to avoid NULLs in math operations
  for (const auto& item : items) {
    double dr = item.discount_rate.value_or(0.0);
    double tr = item.tax_rate.value_or(0.0);

    std::string sql = "INSERT INTO OrderItem (item_id, order_id, product_id, unit_price, quantity, discount_rate, tax_rate) VALUES (" +
                      std::to_string(extract_id(item.item_id)) + ", " +
                      std::to_string(item.order_id) + ", " +
                      std::to_string(item.product_id) + ", " +
                      std::to_string(item.unit_price) + ", " +
                      std::to_string(item.quantity) + ", " +
                      std::to_string(dr) + ", " +
                      std::to_string(tr) + ")";
    conn->execute(sql);
  }

  using namespace sqlgen::literals;

  // Define columns
  auto item_id = "item_id"_c;
  auto order_id = "order_id"_c;
  auto product_id = "product_id"_c;
  auto unit_price = "unit_price"_c;
  auto quantity = "quantity"_c;
  auto discount_rate = "discount_rate"_c;
  auto tax_rate = "tax_rate"_c;

  // Define arithmetic factors
  auto discount_factor = (discount_rate * -0.01) + 1.0;
  auto tax_factor = (tax_rate * 0.01) + 1.0;

  // Calculate metrics
  auto gross_total = (unit_price * quantity).as<"gross_total">();
  auto discounted_total = (unit_price * quantity * discount_factor).as<"discounted_total">();
  auto final_total = (unit_price * quantity * discount_factor * tax_factor).as<"final_total">();
  auto unit_cost = (unit_price * quantity / quantity).as<"unit_cost">();
  auto quantity_group = (quantity % 10).as<"quantity_group">();
  auto estimated_profit = (unit_price * 0.3).as<"estimated_profit">();

  // Build and execute the query
  auto query = sqlgen::select_from<OrderItem>(
      item_id, order_id, product_id, unit_price, quantity,
      discount_rate, tax_rate,
      gross_total, discounted_total, final_total, unit_cost, quantity_group, estimated_profit
  ).to<std::vector<OrderMetrics>>();

  auto res = query(conn);
  if (res.has_value()) {
    return res.value();
  }

  return {};
}

}  // namespace calculate_order_metrics
