 * and return a consolidated view with order_id, customer_name, and amount.
 * It orders the results by amount in descending order.
 * Returns: std::vector<Consolidated>.
 */
std::vector<Consolidated> join_orders_customers_payments() {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Build the query to join Order, Customer, and Payment tables
  auto query = sqlgen::select_from<Order, "Order">(
                   sqlgen::col<"order_id", "Order">,
                   sqlgen::col<"name", "Customer">.as<"customer_name">(),
                   sqlgen::col<"amount", "Payment">)
      | sqlgen::inner_join<Customer, "Customer">(
            sqlgen::col<"customer_id", "Order"> == sqlgen::col<"customer_id", "Customer">)
      | sqlgen::inner_join<Payment, "Payment">(
            sqlgen::col<"order_id", "Order"> == sqlgen::col<"order_id", "Payment">)
      | sqlgen::order_by(sqlgen::col<"amount", "Payment">.desc())
      | sqlgen::to<std::vector<Consolidated>>;

  // Execute the query and return the consolidated dataset
  return query(conn).value();
}

