#pragma once

#include <string>
#include <vector>

#include "sqlgen/literals.hpp"
#include "sqlgen/read.hpp"
#include "sqlgen/sqlite/connect.hpp"
#include "sqlgen/write.hpp"

namespace inventory_bulk_write_and_read {

using sqlgen::PrimaryKey;

struct Inventory {
  PrimaryKey<int> item_id;
  std::string name;
  int quantity;
  std::string location;
};

/**
 * description: inventory_bulk_write_and_read.
 * This function demonstrates how to perform bulk write and read operations on an inventory table.
 * It first drops and recreates the table, then writes the given items to the table.
 * Finally, it reads back the items with quantity > 50, orders them by quantity in descending order,
 * and returns true if at least one item is found.
 * Returns: bool.
 */
bool inventory_bulk_write_and_read(const std::vector<Inventory>& items) {
  // Connect to the SQLite database
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");

  if (!conn_res) {
    return false;
  }

  auto& conn = *conn_res;

  // Drop the table if it exists to ensure a clean slate (recreate logic)
  conn->execute("DROP TABLE IF EXISTS Inventory");

  // Write the batch of items. This will automatically create the table.
  const auto write_res = sqlgen::write(conn, items);

  if (!write_res) {
    return false;
  }

  using namespace sqlgen::literals;

  // Read items where quantity > 50, ordered by quantity descending
  const auto read_res = conn | sqlgen::read<Inventory> |
                        sqlgen::where("quantity"_c > 50) |
                        sqlgen::order_by("quantity"_c.desc());

  // Check if the read operation was successful
  if (!read_res) {
    return false;
  }

  // Return true if at least one item was found
  return !read_res->empty();
}

}  // namespace inventory_bulk_write_and_read
