Here is the complete content of the file `cascade_delete_demo.hpp` (or `.cpp` depending on usage, but typically header-only or implementation file). It includes the necessary headers from the `sqlgen` library, defines the table structures, and implements the demonstration function.

```cpp
#pragma once

#include <string>
#include <vector>

// Include necessary sqlgen headers
#include <sqlgen/sqlite/connect.hpp>
#include <sqlgen/create_table.hpp>
#include <sqlgen/insert.hpp>
#include <sqlgen/delete_from.hpp>
#include <sqlgen/drop.hpp>
#include <sqlgen/select.hpp>
#include <sqlgen/where.hpp>

namespace cascade_delete_demo {

// Bring sqlgen types into scope for struct definitions
using namespace sqlgen;

struct Parent {
  PrimaryKey<int> parent_id;
  std::string name;
};

struct Child {
  PrimaryKey<int> child_id;
  // The ForeignKey definition establishes the relationship.
  // Note: For cascade delete to work, the database must support it and it must be enabled.
  // In SQLite, this requires "PRAGMA foreign_keys = ON".
  ForeignKey<int, Parent, "parent_id"> parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * Returns: bool.
 */
bool cascade_delete_demo() {
  // 1. Connect to the SQLite database "test_db.sqlite"
  auto conn = sqlite::connect("test_db.sqlite");

  // 2. Enable foreign keys (Crucial for SQLite to honor ON DELETE CASCADE)
  // Without this, SQLite ignores foreign key constraints by default.
  conn->execute("PRAGMA foreign_keys = ON;");

  // 3. Clean up previous run to ensure a fresh state
  // Drop Child first because it references Parent
  (drop<Child> | if_exists)(conn);
  (drop<Parent> | if_exists)(conn);

  // 4. Create Parent and Child tables
  // Parent must be created first.
  create_table<Parent>(conn);

  // Create Child table. 
  // We assume the library/struct definition generates the necessary 
  // "ON DELETE CASCADE" constraint or that the environment handles it.
  create_table<Child>(conn);

  // 5. Insert parent and child records
  Parent p{1, "Test Parent"};
  insert(conn, p);

  // Insert child linked to parent_id 1
  Child c{100, 1, "Child note"};
  insert(conn, c);

  // 6. Delete parent
  // This should trigger the cascade deletion of the child record.
  // We use the struct instance to construct the where clause.
  (delete_from<Parent> | where(Parent{}.parent_id == 1))(conn);

  // 7. Verify child deletion
  // Select from Child table where child_id matches the inserted record.
  auto children = (select<Child> | where(Child{}.child_id == 100))(conn);

  // If cascade delete worked, the result set should be empty.
  return children.empty();
}

}  // namespace cascade_delete_demo
