template <typename T>
using PrimaryKey = sqlgen::PrimaryKey<T>;

struct Account {
  PrimaryKey<int> account_id;
  double balance;
  std::string status;
};

/**
 * description: update_set_operations.
 * This function demonstrates how to use set operations in update statements using sqlgen write API.
 * It returns true if the update operations are successful, and false otherwise.
 * Returns: bool.
 */
bool update_set_operations() {
  // Connect to the SQLite database
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return false;
  }
  auto conn = conn_res.value();

  // 1. Create Account table
  auto create_res = conn | sqlgen::create_table<Account>;
  if (!create_res) {
    return false;
  }

  // Insert initial data to update later
  std::vector<Account> accounts = {
      {1, 100.0, "active"},
      {2, 200.0, "inactive"}
  };
  auto write_res = conn | sqlgen::write(accounts);
  if (!write_res) {
    return false;
  }

  // 2. Update balances and statuses using set(...)
  auto update_res = conn | (sqlgen::update<Account>(
      sqlgen::col<"balance">.set(150.0),
      sqlgen::col<"status">.set("premium")
  ) | sqlgen::where(sqlgen::col<"account_id"> == 1));

  if (!update_res) {
    return false;
  }

  // 3. Verify changes persisted
  auto select_res = conn | (sqlgen::select<Account>() | sqlgen::where(sqlgen::col<"account_id"> == 1));
  if (!select_res) {
    return false;
  }

  auto result = select_res.value();
  if (result.empty()) {
    return false;
  }

  // Check if the update was successful
  if (result[0].balance != 150.0 || result[0].status != "premium") {
    return false;
  }

  return true;
}

}  // namespace update_set_operations
