namespace analyze_department_employees {

// Fallback definition in case PrimaryKey is not provided by the environment
template <typename T>
using PrimaryKey = T;

struct Department {
  PrimaryKey<int> department_id;
  std::string department_name;
  std::string location;
};

struct Employee {
  PrimaryKey<int> employee_id;
  int department_id;
  std::string first_name;
  std::string last_name;
  double salary;
};

struct JoinResult {
