using PrimaryKey = T;
using Date = std::string;

struct Product {
  PrimaryKey<int> product_id;
  std::string product_name;
  std::string category;
  double price;
};

struct Sales {
  PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  Date sale_date;
};

struct TopProduct {
  int product_id;
  std::string product_name;
  std::string category;
  double total_sales;
};

/**
 * Description: This function retrieves the top products based on total sales.
 * Returns: std::vector<TopProduct>.
 */
std::vector<TopProduct> get_top_products(size_t limit_count = 10) {
  // 1. Configure the database connection and schema mapping
  auto storage = make_storage("test_db.sqlite",
      make_table("Product",
          make_column("product_id", &Product::product_id, primary_key()),
          make_column("product_name", &Product::product_name),
          make_column("category", &Product::category),
          make_column("price", &Product::price)
      ),
      make_table("Sales",
          make_column("sale_id", &Sales::sale_id, primary_key()),
          make_column("product_id", &Sales::product_id),
          make_column("quantity", &Sales::quantity),
          make_column("sale_date", &Sales::sale_date)
      )
  );

  // 2. Execute the query
  // SQL Equivalent:
  // SELECT p.product_id, p.product_name, p.category, SUM(p.price * s.quantity)
  // FROM Product p
  // INNER JOIN Sales s ON p.product_id = s.product_id
  // GROUP BY p.product_id, p.product_name, p.category
  // ORDER BY total_sales DESC
  // LIMIT limit_count;

  auto rows = storage.select(
      columns(&Product::product_id, 
              &Product::product_name, 
              &Product::category, 
              sum(mul(c(&Product::price), c(&Sales::quantity)))),
      inner_join<Sales>(on(c(&Product::product_id) == c(&Sales::product_id))),
      group_by(&Product::product_id, &Product::product_name, &Product::category),
      order_by(desc(sum(mul(c(&Product::price), c(&Sales::quantity))))),
      limit(limit_count)
  );

  // 3. Transform results into the output struct
  std::vector<TopProduct> result;
  result.reserve(rows.size());

  for (const auto& row : rows) {
      TopProduct tp;
      tp.product_id = std::get<0>(row);
      tp.product_name = std::get<1>(row);
      tp.category = std::get<2>(row);
      // The result of the sum calculation (index 3) is assigned to total_sales
      tp.total_sales = std::get<3>(row);

      result.push_back(tp);
  }

  return result;
}

}  // namespace get_top_products
