namespace weekday_sales_analysis {

using rfl::PrimaryKey;
using rfl::Timestamp;

struct Sales {
  PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  Timestamp<"%Y-%m-%d %H:%M:%S"> sale_time;
};

struct WeekdayStats {
  int weekday;
  int total_quantity;
};

/**
 * Description: This function analyzes sales data to calculate total quantity sold for each weekday.
 * Returns: std::vector<WeekdayStats>.
 */
std::vector<WeekdayStats> weekday_sales_analysis() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Build the query to extract weekday, sum quantities, and group by weekday
  auto query = select_from<Sales>(
                   weekday("sale_time"_c) | as<"weekday">,
                   sum("quantity"_c) | as<"total_quantity">) |
               group_by("weekday"_c) |
               to<std::vector<WeekdayStats>>();

  // Execute the query and return the results
  return query(conn).value();
}

}  // namespace weekday_sales_analysis
