 * Description: This function tracks time metrics for each project, including day, month, year, hour, minute, second, and duration in days.
 * Returns: std::vector<TimeMetrics>.
 */
std::vector<TimeMetrics> project_time_tracking() {
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Build the query following the reference SQL statement
  auto query = select_from<Project, "p">(
                   "p"_c.project_id, 
                   "p"_c.name,
                   day("t"_c.start_time) | as<"day">,
                   month("t"_c.start_time) | as<"month">,
                   year("t"_c.start_time) | as<"year">,
                   hour("t"_c.start_time) | as<"hour">,
                   minute("t"_c.start_time) | as<"minute">,
                   second("t"_c.start_time) | as<"second">,
                   days_between("t"_c.start_time, "t"_c.end_time) | as<"duration_days">)
               | inner_join<TimeLog, "t">("p"_c.project_id == "t"_c.project_id)
               | to<std::vector<TimeMetrics>>;

  // Execute the query and return the results
  return query(conn).value();
}

